    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                result = cache.get(key(args, kwargs))
                if result is None:
