import time

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    class memoized_function:
        def __init__(self, func):
            self.func = func
            self.cache = {}
            self.cache_list = []
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, *args, **kwargs):
            key = args
            if self.typed:
                key += tuple(type(arg) for arg in args)
            key += tuple(kwargs.items())

            if key in self.cache:
                index = self.cache_list.index(key)
                del self.cache_list[index]
                self.cache_list.append(key)
                return self.cache[key]
            else:
                result = self.func(*args, **kwargs)
                self.cache[key] = result
                self.cache_list.append(key)
                if len(self.cache_list) > self.maxsize:
                    del self.cache[self.cache_list[0]]
                    del self.cache_list[0]
                return result

        def __get__(self, obj, objtype=None):
            return self.__call__

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return memoized_function(func)(*args, **kwargs)
        return wrapper

    return decorator

