def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from functools import wraps, total_ordering

    @total_ordering
    class CacheItem:
        __slots__ = ('key', 'value', 'frequency')

        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.frequency = 1

        def __eq__(self, other):
            return self.key == other.key

        def __lt__(self, other):
            return self.frequency < other.frequency

    def decorator(func):
        cache = {}
        queue = []
        hit_count = 0
        miss_count = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hit_count, miss_count

            key = (args, tuple(kwargs.items()))
            if key in cache:
                item = cache[key]
                item.frequency += 1
                while queue and queue[0] < item:
                    del cache[queue.pop(0).key]
                queue.appendleft(item)
                hit_count += 1
                return item.value
            else:
                miss_count += 1
                result = func(*args, **kwargs)
                if maxsize > 0:
                    if len(cache) >= maxsize:
                        oldest = queue.pop()
                        del cache[oldest.key]
                    cache[key] = queue.appendleft(CacheItem(key, result))
                return result

        wrapper.cache_info = lambda: (hit_count, miss_count, maxsize, len(cache))
        return wrapper

    return decorator

