@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import traceback
        import multiprocessing

        def get_stack_string(stack, level):
            return ''.join(traceback.format_list(stack[:level]))

        def get_path_string(path, level):
            if level == 0:
                return ''
            else:
                path.pop()
                return '\n    -> '.join(path)

        try:
            stack = traceback.extract_tb(e.__traceback__)
            path = traceback.get_current_frame().f_locals.pop('path', [''])
            readable = f"{e.__class__.__name__}: {e}\nStack:\n{get_stack_string(stack, min(max_level, len(stack)))}\nPath:\n{get_path_string(path, min(max_path_level, len(path)))}"
        except Exception as ex:
            readable = f"Error formatting exception: {ex}"

        return readable

