def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Helper function to check if classes are equivalent
    def areEquivalent(c1, c2):
        return issubclass(c1, c2) or issubclass(c2, c1)

    # Sort classes to ensure a specific order
    classes.sort(key=hash)

    # Remove unnecessary classes
    result = []
    for cls in classes:
        if not any(areEquivalent(cls, c) for c in result):
            result.append(cls)

    return result

