def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    from .ocfl import reflect
    from .errors import OCFLValidityError
    path = os.path.abspath(path)

    if os.path.exists(path):
        if os.path.isdir(path):
            try:
                reflect(path)
                return True
            except OCFLValidityError as e:
                e.warn()
                if not e.permits_warnings():
                    return False
        elif os.path.isfile(path):
            raise OCFLValidityError("%s is not a directory." % path)

    raise OCFLValidityError("No valid OCFL object found at %s." % path)

