import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if isinstance(commands, str):
        commands = [commands]

    if verbose:
        print(f"Running command: {' '.join(commands) + ' ' + ' '.join(args)}")

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    process = subprocess.Popen([*commands, *args], cwd=cwd, env=env, stderr=stderr)
    output, _ = process.communicate()

    if process.returncode != 0:
        raise subprocess.CalledProcessError(process.returncode, ' '.join(commands), output=output)

    if verbose:
        print(f"Command output: {output.decode().strip()}")

    return output

