def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import configparser
    import os

    config_dict = {}
    log_records = []
    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        if not os.path.exists(filename):
            logger.error(f"Configuration file not found: {filename}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f"Configuration file not found: {filename}", None, None))
            continue

        config = configparser.ConfigParser(allow_no_value=True)
        config.read(filename)

        if overrides:
            for section, overrides_section in overrides.items():
                if section in config:
                    for key, value in overrides_section.items():
                        if value:
                            config[section][key] = value

        if resolve_env:
            for section in config.sections():
                for key, value in config.items(section):
                    if value.startswith('${'):  # Check for environment variable
                        env_var = value[2:-1]
                        if env_var in os.environ:
                            config[section][key] = os.environ[env_var]
                        else:
                            logger.error(f"Environment variable not found: {env_var}")
                            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f"Environment variable not found: {env_var}", None, None))
                            config[section][key] = value  # Keep original value as is

        config_dict[filename] = config

    return config_dict, log_records

